{"command": "cd /workspace/submission/src && cat >> synth.py <<'EOF'


# ================================================================ v2 additions
def morph_cycles(N, M, spec_fn, H, phases=None, tail_zero=False):
    """N samples per cycle; M morph cycles followed by one steady loop cycle.
    spec_fn(c) -> harmonic amplitude vector (len H) for cycle c in 0..M (c==M is the steady one)."""
    ph = 2 * np.pi * np.arange(N) / N
    hs = np.arange(1, H + 1)
    S = np.sin(np.outer(hs, ph))            # (H, N)
    cyc = []
    for c in range(M + 1):
        a = spec_fn(c)
        cyc.append(a @ S)
    x = np.concatenate(cyc)
    return x, (M * N, N)

def lp(h, fc, order=4):
    return 1.0 / np.sqrt(1.0 + (h / fc) ** (2 * order))

def bass_morph():
    N, M, H = 256, 40, 80
    hs = np.arange(1, H + 1)
    def spec(c):
        fc = 7.5 + (46 - 7.5) * np.exp(-c / 5.0)
        amp = 0.86 + 0.14 * np.exp(-c / 6.0)
        return amp * lp(hs, fc, 3) / hs ** 0.92
    x, loop = morph_cycles(N, M, spec, H)
    x = norm(x, 0.95)
    return looped(x, 'bass', C4 * N, loop=loop)

def sub_sine():
    N = 64
    x = cycle(N, {1: 1.0, 2: 0.10, 3: 0.03})
    return looped(norm(x, 0.95), 'sub', C4 * N)

def pluck_morph(name='pluck', duty=0.36, N=128, M=190, tau_a=34.0, fc0=30, fc1=3.2, tau_f=22.0, H=60):
    hs = np.arange(1, H + 1)
    base = np.sin(np.pi * hs * duty) / hs
    def spec(c):
        if c >= M:
            return np.zeros(H)
        fc = fc1 + (fc0 - fc1) * np.exp(-c / tau_f)
        amp = np.exp(-c / tau_a) * (1 - np.exp(-(c + 0.6) / 0.8))
        return amp * base * lp(hs, fc, 3)
    x, loop = morph_cycles(N, M, spec, H)
    x = norm(x, 0.95)
    return looped(x, name, C4 * N, loop=loop)

def chip_pulse(duty=0.25, N=64, H=20, name='chip'):
    hs = np.arange(1, H + 1)
    a = np.sin(np.pi * hs * duty) / hs * lp(hs, 14, 4)
    ph = 2 * np.pi * np.arange(N) / N
    x = a @ np.sin(np.outer(hs, ph) + np.pi / 2 * 0)
    x -= x.mean()
    return looped(norm(x, 0.95), name, C4 * N)

def chord_wave(kind, name, L=8192, k0=100, H=12, rolloff=6.0, tilt=1.0, attack=0, seed=5, decay=None, sub=True, oct_up=False, bright_pan=128):
    """Chord of detuned saw voices. Integer cycle counts per voice => perfectly periodic loop.
    third: min=119, maj=126; fifth=150 (equal-tempered within ~2 cents)."""
    r = np.random.default_rng(seed)
    third = 119 if kind == 'min' else 126
    voices = [(k0, 1.0), (third, 0.9), (150, 0.85)]
    if sub:
        voices.append((k0 // 2, 0.8))
    if oct_up:
        voices.append((k0 * 2, 0.35))
    spec = np.zeros(L // 2 + 1, dtype=complex)
    for c0, g in voices:
        for dv, dg in [(-1, 0.65), (0, 1.0), (1, 0.65)]:
            c = c0 + dv * (1 if c0 > 60 else 0)
            ph0 = r.uniform(0, 2 * np.pi)
            for h in range(1, H + 1):
                if h * c >= L // 2 - 2:
                    break
                a = g * dg / h ** tilt / (1 + (h / rolloff) ** 3)
                spec[h * c] += a * np.exp(1j * (h * ph0))
    x = np.fft.irfft(spec, L)
    x = norm(x, 0.95)
    rate = C4 * L / k0
    if decay is not None:
        t = np.arange(L) / rate
        x = x * np.exp(-t / decay) * (1 - np.exp(-(np.arange(L) + 1) / 60.0))
        x = fade_tail(x, rate, 25)
        return oneshot_rate(x, name, rate)
    if attack:
        pre = x[-attack:] * np.linspace(0, 1, attack) ** 1.5
        x = np.concatenate([pre, x])
        return looped(x, name, rate, loop=(attack, L))
    return looped(x, name, rate)

def oneshot_rate(data, name, rate, vol=64, pan=128):
    rel, ft = rel_ft(rate)
    return Sample(data, name, loop=None, volume=vol, finetune=ft, relnote=rel, pan=pan, bits=16)

def lead_saw(name='lead', attack=260, bright=1.0, seed=3, L=32768, base=256, voices=(-3, -2, -1, 0, 1, 2, 3)):
    s = super_wave(list(voices), H=22, rolloff=10.5 * bright, name=name, seed=seed, L=L, base=base)
    x = s.data
    pre = x[-attack:] * np.linspace(0, 1, attack) ** 1.3
    rate = C4 * L / base
    return looped(np.concatenate([pre, x]), name, rate, loop=(attack, L))

def pad_chord_attack(kind, name, seed=5):
    return chord_wave(kind, name, L=8192, k0=100, H=10, rolloff=4.6, tilt=1.2, attack=5200, seed=seed, sub=True)

def stab_chord(kind, name, seed=9):
    return chord_wave(kind, name, L=8192, k0=100, H=22, rolloff=13.0, tilt=0.95, decay=0.11, seed=seed, sub=False, oct_up=True)

def epiano(name='bell', dur=1.7, ratio=1.0, idx0=2.4, tau_i=0.35, tau_a=0.55, ratio2=7.0, amp2=0.09):
    sr = R1
    n = int(dur * sr); t = np.arange(n) / sr
    fc = C4
    idx = idx0 * np.exp(-t / tau_i) + 0.25
    mod = np.sin(2 * np.pi * fc * ratio * t)
    x = np.sin(2 * np.pi * fc * t + idx * mod)
    x += amp2 * np.sin(2 * np.pi * fc * ratio2 * t + 1.5 * np.sin(2 * np.pi * fc * ratio2 * t)) * np.exp(-t / 0.08)
    env = np.exp(-t / tau_a) * (1 - np.exp(-(np.arange(n) + 1) / 40.0))
    x = x * env
    return oneshot(norm(fade_tail(x, sr, 40), 0.95), name, sr)
